/* ─── Executive Dashboard Styles ─── */
:root {
 --cc-bg-primary: #0a0e1a;
 --cc-bg-card: #131a2e;
 --cc-border: #1e2a45;
 --cc-accent: #00c896;
 --cc-accent-glow: rgba(0, 200, 150, 0.1);
 --cc-warning: #f59e0b;
 --cc-critical: #ef4444;
 --cc-text-primary: #e2e8f0;
 --cc-text-secondary: #94a3b8;
 --cc-radius: 14px;
 --cc-spacing: 24px;
 --cc-blue: #3b82f6;
}

/* ─── Dashboard Container ─── */
.exec-dashboard {
 min-height: 100vh;
 background: var(--cc-bg-primary);
 color: var(--cc-text-primary);
 font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", sans-serif;
}

.exec-dashboard__content {
 padding: var(--cc-spacing);
 max-width: 1440px;
 margin: 0 auto;
}

/* ─── Alert Banner ─── */
.exec-alert-banner {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 10px 24px;
 background: rgba(245, 158, 11, 0.08);
 border-bottom: 1px solid rgba(245, 158, 11, 0.2);
}

.exec-alert-banner__left {
 display: flex;
 align-items: center;
 gap: 10px;
 font-size: 13px;
 color: var(--cc-warning);
}

.exec-alert-banner__right {
 display: flex;
 align-items: center;
}

.exec-alert-banner__label {
 font-size: 10px;
 font-weight: 700;
 letter-spacing: 1px;
 color: var(--cc-text-secondary);
 background: rgba(255, 255, 255, 0.05);
 padding: 3px 8px;
 border-radius: 4px;
}

/* ─── Page Title ─── */
.exec-page-title {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 margin-bottom: 24px;
}

.exec-page-title__heading {
 font-size: 28px;
 font-weight: 700;
 margin: 0 0 4px 0;
 color: var(--cc-text-primary);
}

.exec-page-title__subtitle {
 font-size: 14px;
 color: var(--cc-text-secondary);
 margin: 0;
}

.exec-page-title__right {
 display: flex;
 align-items: center;
 gap: 12px;
 flex-shrink: 0;
}

.exec-page-title__live {
 display: flex;
 align-items: center;
 gap: 6px;
 font-size: 12px;
 color: var(--cc-text-secondary);
 background: rgba(255, 255, 255, 0.03);
 padding: 6px 12px;
 border-radius: 8px;
 border: 1px solid var(--cc-border);
}

.exec-page-title__live-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: var(--cc-accent);
 display: inline-block;
 animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
 0%, 100% {
 opacity: 1;
 }
 50% {
 opacity: 0.4;
 }
}
.exec-page-title__warning {
 font-size: 12px;
 color: var(--cc-warning);
 background: rgba(245, 158, 11, 0.08);
 padding: 6px 12px;
 border-radius: 8px;
 border: 1px solid rgba(245, 158, 11, 0.2);
}

/* ─── KPI Row ─── */
.exec-kpi-row {
 display: grid;
 grid-template-columns: repeat(6, 1fr);
 gap: 16px;
 margin-bottom: 24px;
}

/* ─── KPI Card ─── */
.exec-kpi-card {
 background: var(--cc-bg-card);
 border: 1px solid var(--cc-border);
 border-radius: var(--cc-radius);
 padding: 20px;
 display: flex;
 flex-direction: column;
}

.exec-kpi-card__header {
 margin-bottom: 12px;
}

.exec-kpi-card__label {
 font-size: 12px;
 font-weight: 500;
 color: var(--cc-text-secondary);
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.exec-kpi-card__value {
 font-size: 28px;
 font-weight: 700;
 color: var(--cc-text-primary);
 margin-bottom: 12px;
 flex: 1;
 display: flex;
 align-items: center;
}

.exec-kpi-card__footer {
 font-size: 11px;
 color: var(--cc-text-secondary);
 line-height: 1.4;
}

.exec-kpi-card__trend {
 font-weight: 600;
}

.exec-kpi-card__trend--positive {
 color: var(--cc-accent);
}

.exec-kpi-card__trend--negative {
 color: var(--cc-critical);
}

.exec-kpi-card__context {
 color: var(--cc-text-secondary);
}

/* Pulse Score Donut */
.exec-kpi-card--pulse {
 align-items: center;
}

.exec-kpi-card__donut {
 margin: 4px 0 8px;
}

.exec-kpi-card__donut-score {
 font-size: 24px;
 font-weight: 700;
 fill: var(--cc-text-primary);
}

.exec-kpi-card__donut-label {
 font-size: 11px;
 fill: var(--cc-text-secondary);
}

/* ─── Two Column Layout ─── */
.exec-dashboard__two-col {
 display: grid;
 grid-template-columns: 1.2fr 1fr;
 gap: 20px;
 margin-bottom: 24px;
}

/* ─── Card Generic ─── */
.exec-card {
 background: var(--cc-bg-card);
 border: 1px solid var(--cc-border);
 border-radius: var(--cc-radius);
 padding: 24px;
}

.exec-card__header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 margin-bottom: 20px;
}

.exec-card__title {
 font-size: 16px;
 font-weight: 600;
 color: var(--cc-text-primary);
 margin: 0 0 4px 0;
}

.exec-card__subtitle {
 font-size: 12px;
 color: var(--cc-text-secondary);
 margin: 0;
}

.exec-card__badge {
 font-size: 11px;
 font-weight: 600;
 padding: 4px 10px;
 border-radius: 6px;
 flex-shrink: 0;
}

.exec-card__badge--warning {
 color: var(--cc-critical);
 background: rgba(239, 68, 68, 0.1);
 border: 1px solid rgba(239, 68, 68, 0.2);
}

/* ─── Complaint Chart ─── */
.exec-chart-svg {
 display: block;
 width: 100%;
}

.exec-chart__axis-label {
 font-size: 10px;
 fill: var(--cc-text-secondary);
}

.exec-chart__legend {
 display: flex;
 gap: 20px;
 margin-top: 12px;
}

.exec-chart__legend-item {
 display: flex;
 align-items: center;
 gap: 6px;
 font-size: 11px;
 color: var(--cc-text-secondary);
}

.exec-chart__legend-dot {
 width: 10px;
 height: 10px;
 border-radius: 50%;
}

.exec-chart__legend-dot--blue {
 background: var(--cc-blue);
}

.exec-chart__legend-dot--green {
 background: var(--cc-accent);
}

/* ─── Red Alerts ─── */
.exec-alerts-list {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.exec-alert-item {
 display: flex;
 align-items: center;
 gap: 12px;
 padding: 12px;
 border-radius: 10px;
 transition: background 0.15s ease;
 cursor: pointer;
}

.exec-alert-item:hover {
 background: rgba(255, 255, 255, 0.03);
}

.exec-alert-item__dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: var(--cc-critical);
 flex-shrink: 0;
}

.exec-alert-item__content {
 flex: 1;
 min-width: 0;
}

.exec-alert-item__header {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-bottom: 3px;
}

.exec-alert-item__title {
 font-size: 13px;
 font-weight: 600;
 color: var(--cc-text-primary);
}

.exec-alert-item__id {
 font-size: 11px;
 color: var(--cc-text-secondary);
}

.exec-alert-item__desc {
 font-size: 11px;
 color: var(--cc-text-secondary);
 margin: 0;
 white-space: nowrap;
 overflow: hidden;
 text-overflow: ellipsis;
}

.exec-alert-item__right {
 display: flex;
 flex-direction: column;
 align-items: flex-end;
 gap: 2px;
 flex-shrink: 0;
 color: var(--cc-text-secondary);
}

.exec-alert-item__time {
 font-size: 11px;
 color: var(--cc-text-secondary);
 white-space: nowrap;
}

/* ─── City Bar Chart ─── */
.exec-bar-chart {
 display: flex;
 gap: 8px;
 height: 200px;
}

.exec-bar-chart__y-axis {
 display: flex;
 flex-direction: column;
 justify-content: space-between;
 padding: 0 4px 24px 0;
}

.exec-bar-chart__y-label {
 font-size: 10px;
 color: var(--cc-text-secondary);
 text-align: right;
 width: 30px;
}

.exec-bar-chart__bars {
 display: flex;
 flex: 1;
 align-items: flex-end;
 gap: 8px;
 padding-bottom: 24px;
 border-bottom: 1px solid var(--cc-border);
}

.exec-bar-chart__col {
 flex: 1;
 display: flex;
 flex-direction: column;
 align-items: center;
 height: 100%;
}

.exec-bar-chart__bar-wrapper {
 flex: 1;
 width: 100%;
 display: flex;
 align-items: flex-end;
 justify-content: center;
}

.exec-bar-chart__bar {
 width: 70%;
 background: var(--cc-blue);
 border-radius: 4px 4px 0 0;
 min-height: 4px;
 transition: height 0.3s ease;
}

.exec-bar-chart__bar:hover {
 background: #60a5fa;
}

.exec-bar-chart__x-label {
 font-size: 9px;
 color: var(--cc-text-secondary);
 margin-top: 8px;
 text-align: center;
 white-space: nowrap;
}

/* ─── Top Worst Stores ─── */
.exec-stores-list {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.exec-store-item {
 display: flex;
 align-items: center;
 gap: 12px;
 padding: 12px;
 border-radius: 10px;
 cursor: pointer;
 transition: background 0.15s ease;
}

.exec-store-item:hover {
 background: rgba(255, 255, 255, 0.03);
}

.exec-store-item__content {
 flex: 1;
 min-width: 0;
}

.exec-store-item__name {
 display: block;
 font-size: 13px;
 font-weight: 600;
 color: var(--cc-text-primary);
 margin-bottom: 2px;
}

.exec-store-item__info {
 font-size: 11px;
 color: var(--cc-text-secondary);
}

.exec-store-item__right {
 display: flex;
 flex-direction: column;
 align-items: flex-end;
 flex-shrink: 0;
}

.exec-store-item__score {
 font-size: 22px;
 font-weight: 700;
 color: var(--cc-critical);
}

.exec-store-item__change {
 font-size: 10px;
 color: var(--cc-critical);
}

.exec-store-item__chevron {
 color: var(--cc-text-secondary);
 flex-shrink: 0;
}

/* ─── Heatmap ─── */
.exec-card--heatmap {
 margin-bottom: 24px;
}

.exec-heatmap__legend {
 display: flex;
 gap: 16px;
 align-items: center;
}

.exec-heatmap__legend-item {
 display: flex;
 align-items: center;
 gap: 6px;
 font-size: 11px;
 color: var(--cc-text-secondary);
}

.exec-heatmap__legend-swatch {
 width: 12px;
 height: 12px;
 border-radius: 3px;
}

.exec-heatmap__grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 24px;
}

.exec-heatmap__column {
 display: flex;
 flex-direction: column;
 gap: 10px;
}

.exec-heatmap__row {
 display: flex;
 align-items: center;
 gap: 12px;
}

.exec-heatmap__city {
 font-size: 12px;
 color: var(--cc-text-secondary);
 width: 90px;
 flex-shrink: 0;
 text-align: right;
}

.exec-heatmap__cells {
 display: flex;
 gap: 3px;
 flex-wrap: wrap;
}

.exec-heatmap__cell {
 width: 12px;
 height: 12px;
 border-radius: 3px;
 cursor: pointer;
 transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.exec-heatmap__cell:hover {
 transform: scale(1.5);
 box-shadow: 0 0 8px rgba(255, 255, 255, 0.2);
}

/* ─── Responsive ─── */
@media (max-width: 1200px) {
 .exec-kpi-row {
 grid-template-columns: repeat(3, 1fr);
 }
 .exec-dashboard__two-col {
 grid-template-columns: 1fr;
 }
}
@media (max-width: 768px) {
 .exec-kpi-row {
 grid-template-columns: repeat(2, 1fr);
 }
 .exec-heatmap__grid {
 grid-template-columns: 1fr;
 }
 .exec-page-title {
 flex-direction: column;
